      "text": "; @module   arith16\n; @summary  8- and 16-bit multiply, divide and modulo.\n; @exports  Mul8, DivModU8, DivModI8, Mul16, DivModU16, DivModI16\n; @exports  AbsI8, AbsI16, SgnI8, SgnI16\n; @abi      AbsI8(a)\n; @abi      AbsI16(hl)\n; @abi      SgnI8(a)\n; @abi      SgnI16(hl)\n;\n; Operands follow runtime-abi.md §7: 8-bit in A and H, 16-bit in HL and DE. A product keeps its low\n; 8 or 16 bits, the same for signed and unsigned operands. Signed division truncates towards zero\n; and the remainder is the remainder of the magnitudes, never negative: -100 MOD 3 is 1, as ZX BASIC\n; gives (the semantics annex's mod-sign). Division by zero gives the dividend's magnitude as the\n; remainder and a quotient of the magnitudes with every bit set, then given the quotient's sign:\n; -7 / 0 is 1 (integer-division-by-zero).\n\n; ------------------------------------------------------------------------------------------------\n; A * H. Out: A. Changes F, B, H, L.\n#ifmod Next\n; --- The Next: the Z80N's 8x8 multiply (DE kept, as the contract promises)\nMul8:\n    push de\n    ld d,a\n    ld e,h\n    mul d,e\n    ld a,e\n    pop de\n    ret\n#else\nMul8:\n    ld l,a\n    xor a\n    ld b,8\nMul8Loop:\n    add a,a\n    sla h\n    jr nc,Mul8Next\n    add a,l\nMul8Next:\n    djnz Mul8Loop\n    ret\n#endif\n\n; ------------------------------------------------------------------------------------------------\n; A / H, unsigned. Out: A = quotient, L = remainder. Changes F, B, C.\nDivModU8:\n    ld c,a                  ; C = dividend, becomes the quotient\n    xor a                   ; A = remainder\n    ld b,8\nDivModU8Loop:\n    sla c\n    rla\n    jr c,DivModU8Sub        ; nine bits: certainly not less than the divisor\n    cp h\n    jr c,DivModU8Next\nDivModU8Sub:\n    sub h\n    inc c\nDivModU8Next:\n    djnz DivModU8Loop\n    ld l,a\n    ld a,c\n    ret\n\n; ------------------------------------------------------------------------------------------------\n; A / H, signed. Out: A = H = quotient, L = remainder (of the magnitudes). Changes F, B, C.\nDivModI8:\n    ld b,a                  ; B = dividend\n    xor h\n    ld c,a                  ; bit 7 of C: the quotient's sign\n    ld a,h\n    or a\n    jp p,DivModI8Pos\n    neg\n    ld h,a                  ; H = |divisor|\nDivModI8Pos:\n    ld a,b\n    or a\n    jp p,DivModI8Div\n    neg                     ; A = |dividend|\nDivModI8Div:\n    push bc                 ; S: [C]\n    call DivModU8\n    pop bc                  ; C = quotient sign                    S: []\n    bit 7,c\n    jr z,DivModI8Done\n    neg\nDivModI8Done:\n    ld h,a                  ; H = quotient\n    ret\n\n; ------------------------------------------------------------------------------------------------\n; HL * DE. Out: HL. Changes AF, BC, DE.\n#ifmod Next\n; --- The Next: the low 16 bits of the product from three 8x8 multiplies,\n; --- aL*bL + ((aH*bL + aL*bH) << 8)\nMul16:\n    ld b,h                  ; B = aH\n    ld c,l                  ; C = aL\n    ld h,d                  ; H = bH\n    ld l,e                  ; L = bL\n    ld d,c                  ; DE = aL, bL\n    mul d,e                 ; DE = aL*bL\n    push de\n    ld d,b\n    ld e,l\n    mul d,e                 ; E = low(aH*bL)\n    ld a,e\n    ld d,c\n    ld e,h\n    mul d,e                 ; E = low(aL*bH)\n    add a,e\n    pop hl                  ; HL = aL*bL\n    add a,h\n    ld h,a\n    ret\n#else\nMul16:\n    ld b,h\n    ld c,l                  ; BC = multiplicand\n    ld hl,0\n    ld a,16\nMul16Loop:\n    add hl,hl\n    ex de,hl\n    add hl,hl               ; carry = the multiplier's next bit\n    ex de,hl\n    jr nc,Mul16Next\n    add hl,bc\nMul16Next:\n    dec a\n    jr nz,Mul16Loop\n    ret\n#endif\n\n; ------------------------------------------------------------------------------------------------\n; HL / DE, unsigned. Out: HL = quotient, DE = remainder. Changes AF, BC.\nDivModU16:\n    ld a,h\n    ld c,l                  ; AC = dividend, becomes the quotient\n    ld hl,0                 ; HL = remainder\n    ld b,16\nDivModU16Loop:\n    sla c\n    rla\n    adc hl,hl\n    jr c,DivModU16Sub       ; seventeen bits: certainly not less than the divisor\n    sbc hl,de\n    jr nc,DivModU16Set\n    add hl,de\n    djnz DivModU16Loop\n    jr DivModU16Done\nDivModU16Sub:\n    or a\n    sbc hl,de\nDivModU16Set:\n    inc c\n    djnz DivModU16Loop\nDivModU16Done:\n    ex de,hl\n    ld h,a\n    ld l,c\n    ret\n\n; ------------------------------------------------------------------------------------------------\n; HL / DE, signed. Out: HL = quotient, DE = remainder (of the magnitudes). Changes AF, BC.\nDivModI16:\n    ld a,h\n    xor d\n    push af                 ; S: [quotient sign]\n    ld a,h\n    or a\n    call m,DivModNegHL\n    ex de,hl\n    ld a,h\n    or a\n    call m,DivModNegHL\n    ex de,hl\n    call DivModU16\n    pop af                  ; S: []\n    or a\n    ret p\n    ; fall through: negate the quotient\n\n; HL = -HL. Changes AF.\nDivModNegHL:\n    xor a\n    sub l\n    ld l,a\n    sbc a,a\n    sub h\n    ld h,a\n    ret\n\n; ------------------------------------------------------------------------------------------------\n; ABS of a signed byte A (-128 stays -128, as its negation wraps). Out: A. Changes F.\nAbsI8:\n    or a\n    ret p\n    neg\n    ret\n\n; ABS of a signed word HL (-32768 stays). Out: HL. Changes AF.\nAbsI16:\n    bit 7,h\n    ret z\n    jp DivModNegHL\n\n; SGN of a signed byte A: -1, 0 or 1. Out: A. Changes F.\nSgnI8:\n    or a\n    ret z\n    ld a,1\n    ret p\n    ld a,$ff\n    ret\n\n; SGN of a signed word HL: -1, 0 or 1. Out: A. Changes F.\nSgnI16:\n    ld a,h\n    or a\n    ld a,$ff\n    ret m\n    ld a,h\n    or l\n    ret z\n    ld a,1\n    ret\n"
