      "text": "; @module   arith32\n; @summary  32-bit multiply, divide and modulo (Long and ULong).\n; @exports  Mul32, DivU32, ModU32, DivI32, ModI32, AbsI32, SgnI32\n; @abi      AbsI32(dehl)\n; @abi      SgnI32(dehl)\n;\n; Every routine takes its left operand on the stack under the return address (pushed high word\n; first, so the low word is on top) and its right operand in DE:HL (DE = the high word); it removes\n; the left operand and gives the result in DE:HL. That is where the compiler's stack machine has\n; the operands of a binary operator. Division truncates towards zero; a signed remainder is the\n; remainder of the magnitudes, never negative, as ZX BASIC gives (the semantics annex's mod-sign).\n; Dividing by zero gives a quotient with every bit set and the dividend's magnitude as the remainder\n; (integer-division-by-zero).\n;\n; The routines keep their operands in memory, so they are not re-entrant: an interrupt handler must\n; not use 32-bit multiply or divide while the program it interrupted is in one.\n\n; ------------------------------------------------------------------------------------------------\n; The low 32 bits of left * right (the same for signed and unsigned). Changes AF, BC.\nMul32:\n    call Arith32Operands\n    ld hl,0\n    ld de,0                 ; DE:HL = the product so far\n    ld b,32\nMul32Loop:\n    add hl,hl\n    ex de,hl\n    adc hl,hl\n    ex de,hl                ; product <<= 1\n    push hl\n    ld hl,Arith32B\n    sla (hl)\n    inc hl\n    rl (hl)\n    inc hl\n    rl (hl)\n    inc hl\n    rl (hl)                 ; carry = the multiplier's next bit, from the top\n    pop hl\n    jr nc,Mul32Next\n    push bc\n    ld bc,(Arith32A)\n    add hl,bc\n    ex de,hl\n    ld bc,(Arith32A+2)\n    adc hl,bc\n    ex de,hl                ; product += multiplicand\n    pop bc\nMul32Next:\n    djnz Mul32Loop\n    ret\n\n; ------------------------------------------------------------------------------------------------\n; left / right and left MOD right. Change AF, BC.\nDivU32:\n    call Arith32Operands\n    call DivMod32\nArith32Quotient:\n    ld hl,(Arith32A)\n    ld de,(Arith32A+2)\n    ret\n\nModU32:\n    call Arith32Operands\n    call DivMod32\nArith32Remainder:\n    ld hl,(Arith32R)\n    ld de,(Arith32R+2)\n    ret\n\nDivI32:\n    call Arith32Operands\n    call DivModSigned32\n    ld a,(Arith32QSign)\n    or a\n    ld hl,Arith32A\n    call m,Neg32Mem\n    jr Arith32Quotient\n\nModI32:\n    call Arith32Operands\n    call DivModSigned32     ; the remainder of the magnitudes stays positive\n    jr Arith32Remainder\n\n; ------------------------------------------------------------------------------------------------\n; Moves the right operand (DE:HL) to Arith32B and the left one (under the caller's return address)\n; to Arith32A, removing it from the stack. Changes BC, DE, HL.\nArith32Operands:\n    ld (Arith32B),hl\n    ld (Arith32B+2),de\n    pop bc                  ; BC = the return address into the routine\n    pop de                  ; DE = the caller's return address\n    pop hl\n    ld (Arith32A),hl\n    pop hl\n    ld (Arith32A+2),hl\n    push de\n    push bc\n    ret\n\n; Arith32A / Arith32B, unsigned, by restoring division: the quotient replaces Arith32A, the\n; remainder is in Arith32R. Changes AF, BC, DE, HL.\nDivMod32:\n    ld hl,0\n    ld (Arith32R),hl\n    ld (Arith32R+2),hl\n    ld b,32\nDivMod32Loop:\n    ld hl,Arith32A          ; Arith32R follows it: shift the 64 bits R:A left by one\n    sla (hl)\n    inc hl\n    rl (hl)\n    inc hl\n    rl (hl)\n    inc hl\n    rl (hl)\n    inc hl\n    rl (hl)\n    inc hl\n    rl (hl)\n    inc hl\n    rl (hl)\n    inc hl\n    rl (hl)\n    sbc a,a\n    ld c,a                  ; C = $FF: the remainder has 33 bits, so it is not less than the divisor\n    ld hl,(Arith32R)\n    ld de,(Arith32B)\n    or a\n    sbc hl,de\n    push hl\n    ld hl,(Arith32R+2)\n    ld de,(Arith32B+2)\n    sbc hl,de\n    pop de                  ; HL:DE = remainder - divisor; carry = it went below zero\n    jr nc,DivMod32Take\n    inc c\n    jr nz,DivMod32Next      ; C was 0: the remainder is less than the divisor\nDivMod32Take:\n    ld (Arith32R),de\n    ld (Arith32R+2),hl\n    ld hl,Arith32A\n    inc (hl)                ; the quotient bit (the shift left bit 0 clear)\nDivMod32Next:\n    djnz DivMod32Loop\n    ret\n\n; DivMod32 of the operands' magnitudes, noting the signs the results take. Changes AF, BC, DE, HL.\nDivModSigned32:\n    ld a,(Arith32A+3)\n    ld (Arith32RSign),a\n    ld hl,Arith32B+3\n    xor (hl)\n    ld (Arith32QSign),a\n    ld a,(Arith32A+3)\n    or a\n    ld hl,Arith32A\n    call m,Neg32Mem\n    ld a,(Arith32B+3)\n    or a\n    ld hl,Arith32B\n    call m,Neg32Mem\n    jr DivMod32\n\n; Negates the 32-bit value at HL. Changes AF, HL.\nNeg32Mem:\n    xor a\n    sub (hl)\n    ld (hl),a\n    inc hl\n    ld a,0\n    sbc a,(hl)\n    ld (hl),a\n    inc hl\n    ld a,0\n    sbc a,(hl)\n    ld (hl),a\n    inc hl\n    ld a,0\n    sbc a,(hl)\n    ld (hl),a\n    ret\n\n; ------------------------------------------------------------------------------------------------\n; ABS of a signed DE:HL (-2^31 stays). Out: DE:HL. Changes AF.\nAbsI32:\n    bit 7,d\n    ret z\n    xor a\n    sub l\n    ld l,a\n    ld a,0\n    sbc a,h\n    ld h,a\n    ld a,0\n    sbc a,e\n    ld e,a\n    ld a,0\n    sbc a,d\n    ld d,a\n    ret\n\n; SGN of a signed DE:HL: -1, 0 or 1. Out: A. Changes F.\nSgnI32:\n    ld a,d\n    or a\n    ld a,$ff\n    ret m\n    ld a,d\n    or e\n    or h\n    or l\n    ret z\n    ld a,1\n    ret\n\nArith32A:\n    .defs 4\nArith32R:                   ; must follow Arith32A (DivMod32 shifts them as one)\n    .defs 4\nArith32B:\n    .defs 4\nArith32QSign:\n    .defb 0\nArith32RSign:\n    .defb 0\n"
